let currentPath = '/';
function brand(distributor=false) {
  if(!distributor)return PublicHeader.logo();
  const live=distributor&&!Account.isDemo()&&Account.activeCompany;
  const logoUrl=live?live.brand?.logo_url:distributor?theme.logo:'';
  return `<span class="brand-mark">${logoUrl?`<img class="tenant-logo" src="${escapeHTML(logoUrl)}" alt="" referrerpolicy="no-referrer"><span class="logo-fallback">${icon('sun')}</span>`:icon('sun')}</span><span class="brand-text">${distributor ? escapeHTML(live?(live.brand?.public_name||live.name):theme.name) : 'MY SOLAR'}<small>${distributor ? 'BUSINESS WORKSPACE' : 'A BRIGHTER EVERYDAY'}</small></span>`;
}
function avatar(size='') { return SIA.avatar(size); }
function status(label, tone='neutral') { return `<span class="status ${tone}">${label}</span>`; }
function heading(eyebrow,title,description,action='') { return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="muted">${description}</p></div>${action}</div>`; }
function demoNotice() { return `<div class="demo-notice">${icon('leaf')}<span><strong>A little look at what’s ahead.</strong> Phase 1 preview · All names and records are fictional. Business actions are inactive.</span>${link('/states','View UI states')}</div>`; }
function publicHeader() { return PublicHeader.markup(); }
function languageSelect() { const choices=window.CustomerLocale?CustomerLocale.languages:[['en','English','English'],['ml','മലയാളം','Malayalam'],['ta','தமிழ்','Tamil']];return `<label class="language"><span class="sr-only">${t('Interface language')}</span><select id="language" aria-label="${escapeHTML(t('Interface language'))}">${choices.map(([code,native,name])=>`<option value="${code}" ${locale===code?'selected':''}>${escapeHTML(native)}${native===name?'':' · '+escapeHTML(name)}</option>`).join('')}</select></label>`; }
function sidebar(channel) {
  if(window.BossDashboard?.enabled()&&currentPath==='/distributor/dashboard')return `<aside class="sidebar boss-sidebar ${mobileOpen?'open':''}"><div class="sidebar-brand">${link('/',brand(),'brand')}${button(icon('close'),'menu','icon-button sidebar-close')}</div><nav aria-label="Workspace navigation">${BossDashboard.navigation()}</nav><div class="sidebar-bottom"><div class="workspace-person"><span class="person">${escapeHTML(Account.person().name.slice(0,2).toUpperCase())}</span><span><strong>${escapeHTML(Account.person().name)}</strong><small>${escapeHTML(Account.person().role)}</small></span></div></div></aside>`;
  const setupNav=!Account.isDemo()&&channel==='distributor'?[['/distributor/catalogue','sun','Energy catalogue'],['/distributor/offers','box','My offers'],['/distributor/service-areas','pin','Service areas'],['/distributor/setup','file','Company setup'],['/distributor/branding','sun','Brand identity'],['/distributor/team','users','Team']]:[];
  const nav=[...(channel==='customer'?customerNav:distributorNav),...setupNav,...(!Account.isDemo()?[['/'+channel+'/notifications','bell','Notifications']]:[])].filter(([path])=>Account.navAllowed(path));
  const person=Account.person();const demo=Account.isDemo();const sia=channel==='distributor'&&Account.navAllowed('/sia');
  return `<aside class="sidebar ${mobileOpen?'open':''}"><div class="sidebar-brand">${link('/',brand(channel==='distributor'),'brand')}${button(icon('close'),'menu','icon-button sidebar-close')}</div><p class="nav-caption">${channel==='customer'?'YOUR SOLAR JOURNEY':'MY SOLAR OS'}</p><nav aria-label="Workspace navigation">${channel==='distributor'?Workspace.navigationMarkup(currentPath):nav.map(([path,i,label])=>link(path,icon(i)+`<span>${t(label)}</span>`+(currentPath===path?'<span class="nav-dot"></span>':''),`nav-item ${currentPath===path?'active':''}`)).join('')}</nav>${sia?`<p class="nav-caption">YOUR GROWTH PARTNER</p>${link('/sia',icon('spark')+`<span>${t('Virtual CEO')}</span><span class="new-tag">SIA</span>`,`nav-item ${currentPath==='/sia'?'active':''}`)}<div class="sidebar-sia">${avatar()}<strong>A clearer day starts here.</strong><p>Your business, with a little more perspective.</p>${link('/sia','Meet SIA '+icon('arrow'))}</div>`:''}<div class="sidebar-bottom">${!demo&&channel==='distributor'?link('/companies',icon('compare')+'<span>Switch company</span>','nav-item'):''}${!demo?link('/account-security',icon('settings')+'<span>Account security</span>','nav-item'):''}${link('/',icon('sun')+`<span>${t('Marketplace')}</span>`,'nav-item')}${!demo?'<button class="nav-item account-logout" data-account-action="logout">'+icon('logout')+'<span>Sign out</span></button>':link('/distributor/login','Exit demo · Sign in','nav-item')}<div class="workspace-person"><span class="person">${escapeHTML(person.name.slice(0,2).toUpperCase())}</span><span><strong>${escapeHTML(person.name)}</strong><small>${escapeHTML(person.role)}</small></span></div><div class="provider">Powered by <strong>AIRA Labs</strong></div></div></aside>`;
}
function workspaceHeader(channel) {if(window.BossDashboard?.enabled()&&currentPath==='/distributor/dashboard')return BossDashboard.header();return `<header class="workspace-header"><div class="breadcrumbs">${button(icon('menu'),'menu','icon-button mobile-toggle')}<span>${channel==='customer'?'Customer workspace':'MY Solar OS'}</span>${icon('chevron')}<strong>${t(routes[currentPath]?.[1] || 'Overview')}</strong></div><div class="header-actions">${status(Account.isDemo()?'FICTIONAL DEMO':'SIGNED IN','gold')}${languageSelect()}${Account.isDemo()?button(icon('bell'),'notifications','icon-button'):Account.navAllowed('/'+channel+'/notifications')?link('/'+channel+'/notifications',icon('bell')+'<span class="sr-only">Notifications</span>','icon-button'):''}<span class="person small">${escapeHTML(Account.person().name.slice(0,2).toUpperCase())}</span></div></header>`;}
function footer() { if(currentPath==='/')return Landing.footer(); return `<footer class="footer"><div>${link('/',brand(),'brand')}<p>Good energy. Better possibilities.</p></div><div>${link('/customer','For customers')}${link('/distributor','For distributors')}<a href="/support">Support</a><a href="/privacy">Privacy draft</a><a href="/terms">Terms draft</a>${link('/app-info','Mobile access')}<small>Technology by AIRA Labs · Your energy journey, connected</small></div></footer>`; }
function solarArtwork() { return `<svg class="solar-art" viewBox="0 0 640 480" role="img" aria-label="Illustration of a home powered by rooftop solar"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#e8ebd9"/><stop offset="1" stop-color="#f4ecda"/></linearGradient><linearGradient id="panel" x2="0" y2="1"><stop stop-color="#283d45"/><stop offset="1" stop-color="#142d36"/></linearGradient><pattern id="cells" width="29" height="24" patternUnits="userSpaceOnUse"><rect width="29" height="24" fill="url(#panel)"/><path d="M0 0h29v24H0Z" fill="none" stroke="#86a7aa" stroke-width=".7"/></pattern></defs><rect width="640" height="480" rx="24" fill="url(#sky)"/><circle cx="486" cy="94" r="45" fill="#e7ba65"/><path d="M0 330Q120 250 280 330T640 300V480H0Z" fill="#bac3a6"/><path d="M0 385Q140 305 370 378T640 345V480H0Z" fill="#9dab88"/><path d="M144 266h344v140H144Z" fill="#f4f0e5"/><path d="m108 276 118-146h199l100 146Z" fill="#7a5945"/><path d="m151 257 85-106h178l73 106Z" fill="url(#cells)" stroke="#c6d3cd" stroke-width="4"/><path d="M341 284h94v122h-94Z" fill="#d0c1a4"/><path d="M354 302h67v104h-67Z" fill="#655645"/><rect x="184" y="297" width="105" height="65" rx="2" fill="#6f9293"/><path d="M236 298v64m-50-32h101" stroke="#f3eee1" stroke-width="5"/><path d="M124 406h386v12H124Z" fill="#ded6c6"/><path d="M327 419h126l40 61H287Z" fill="#d2c5a8"/><path d="M75 415v-93m492 100v-122" stroke="#677158" stroke-width="8"/><ellipse cx="75" cy="310" rx="30" ry="53" fill="#778869"/><ellipse cx="565" cy="283" rx="33" ry="63" fill="#647c5d"/><path d="M0 445q100-25 171 0m335-5q80-22 134 0" fill="none" stroke="#869873" stroke-width="25"/></svg>`; }
