const categories = [['sun','Rooftop solar','A brighter roof. A smarter home.','Explore solutions','/products/rooftop-solar','solar'],['box','Battery storage','Keep good energy for later.','View category','/products?category=battery','battery'],['wallet','Inverters','The connection that powers it all.','View category','/products?category=inverter','inverter']];
function categoryCards() { return `<div class="category-grid">${categories.map(([i,title,desc,cta,path,cls])=>`<a href="#${path}" class="category-card ${cls}"><div class="category-illustration">${icon(i)}<span class="energy-line"></span></div><div class="category-info"><h3>${title}</h3><p>${desc}</p><span>${cta}${icon('arrow')}</span></div></a>`).join('')}</div>`; }
function entry(channel) {
  const d=channel==='distributor';
  return `<section class="entry-hero"><p class="eyebrow">${d?'THE DISTRIBUTOR BUSINESS WORKSPACE':'YOUR CUSTOMER WORKSPACE'}</p><h1>${d?'Your business.<br>A clearer way forward.':'Your solar journey.<br>All in one place.'}</h1><p class="muted">${d?'One calm place for your company, your people and your next opportunity.':'A personal space for your next step towards solar.'}</p><div class="hero-actions">${link(d?'/distributor/dashboard':'/customer/dashboard','Open your workspace '+icon('arrow'),'btn primary')}${link(d?'/distributor/login':'/customer/login','Sign in','btn secondary')}</div>${link(`${d?'/distributor':'/customer'}/dashboard?demo=1`,'Explore the fictional demo '+icon('arrow'),'text-link')}</section><section class="feature-grid section">${(d?[['users','Keep every opportunity close','Keep leads, customers and conversations in your company workspace.'],['tool','Give every project a clear path','Follow recorded installation milestones and assigned team tasks.'],['spark','Meet your Virtual CEO','Preview SIA’s dedicated space for summaries and approvals.']]:[['sun','Find your fit','Explore published energy products and distributor storefronts.'],['compare','See the whole picture','Compare your received quotations and ask for clarification.'],['tool','Know what comes next','Follow your confirmed orders and recorded installation progress.']]).map(([i,title,desc])=>`<article class="panel feature">${icon(i)}<h3>${title}</h3><p class="muted">${desc}</p></article>`).join('')}</section><div class="info-callout">${icon('help')}<p>Your workspace shows your authorized records. Business actions require a connection and your explicit confirmation. The separate demo contains clearly fictional examples.</p></div><div class="center-cta">${link(d?'/distributor/onboarding':'/register',d?'Register your company '+icon('arrow'):'Create your account '+icon('arrow'),'text-link')}</div>`;
}
function stats(items) { return `<div class="stats-grid">${items.map(([i,label,value,detail])=>`<article class="stat-card"><div class="stat-top"><span>${label}</span>${icon(i)}</div><strong>${value}</strong><small>${detail}</small></article>`).join('')}</div>`; }
const projects = [['DK','Devika Kumar','3 kW · Rooftop solar','Site survey','gold','Kochi'],['RN','Rahul Nair','5 kW · Rooftop solar','Installation','blue','Aluva'],['MS','Meera Suresh','3 kW · Rooftop solar','Documentation','neutral','Thrissur']];
function projectTable() { return `<div class="table-scroll"><table><caption class="sr-only">Fictional project examples</caption><thead><tr><th>Customer</th><th>Solution</th><th>Stage</th><th>Location</th><th><span class="sr-only">Details</span></th></tr></thead><tbody>${projects.map(([initial,name,solution,stage,tone,location])=>`<tr><td><span class="table-person"><span class="person">${initial}</span><strong>${name}<small>Fictional customer</small></strong></span></td><td>${solution}</td><td>${status(stage,tone)}</td><td>${location}</td><td>${link('/distributor/projects',icon('chevron'),'table-link')}</td></tr>`).join('')}</tbody></table></div>`; }
function distributorDashboard() { return `${heading('A LITTLE CLARITY FOR YOUR DAY','Good morning, Arjun <span class="greeting-sun">☀</span>','Here’s a look at your business. Let’s make today count.',link('/distributor/leads',icon('users')+'View leads','btn primary'))}${demoNotice()}${stats([['users','Open leads','12','Fictional pipeline'],['file','Quotations to follow up','08','Fictional quotations'],['tool','Active projects','06','Fictional projects'],['wallet','Payments pending','₹2.4L','Illustrative amount']])}<div class="dashboard-columns"><section class="panel today-panel"><div class="panel-heading"><div><h2>A little focus for today</h2><p class="muted">The next few steps, all in one place.</p></div>${status('3 EXAMPLES')}</div><div class="task-list">${[['pin','Site survey with Devika Kumar','Kochi · Sample appointment','/distributor/projects','View projects'],['file','Follow up on a quotation','Rahul Nair · 5 kW rooftop solar','/distributor/quotations','View quotations'],['box','Review inventory levels','Solar panels · Sample stock reminder','/distributor/inventory','View inventory']].map(([i,title,sub,path,label],n)=>`<a class="task" href="#${path}"><span class="task-icon tone-${n}">${icon(i)}</span><span><strong>${title}</strong><small>${sub}</small></span><span class="task-action">${label}${icon('chevron')}</span></a>`).join('')}</div></section><section class="sia-card"><div class="sia-card-top"><span class="eyebrow">YOUR VIRTUAL CEO</span>${status('PREVIEW','gold')}</div><div class="sia-intro">${avatar()}<div><h2>A little perspective.<br>A lot of possibility.</h2><p>SIA, by AIRA Labs</p></div></div><p>Your space to understand your business, spot opportunities and decide what comes next.</p>${link('/sia','Open SIA command centre '+icon('arrow'),'btn light')}</section></div><section class="panel"><div class="panel-heading"><div><h2>Projects moving forward</h2><p class="muted">A sample view of your installation pipeline.</p></div>${link('/distributor/projects','All projects '+icon('arrow'),'text-link')}</div>${projectTable()}</section><div class="bottom-note">${icon('leaf')} One step at a time. Build a business that grows with you.</div>`; }
function customerDashboard() { return `${heading('YOUR ENERGY JOURNEY','Welcome, Devika.','A clearer view of your next step towards solar.',link('/products','Explore solutions '+icon('arrow'),'btn primary'))}${demoNotice()}${stats([['file','Enquiries','02','Fictional examples'],['compare','Quotations','03','Fictional examples'],['box','Orders','01','Fictional example'],['tool','Installation','Survey','Illustrative stage']])}<div class="dashboard-columns"><section class="panel"><div class="panel-heading"><h2>Your rooftop solar journey</h2>${status('DEMO','gold')}</div><div class="journey-preview"><span class="round-icon">${icon('sun')}</span><h2>A brighter home is taking shape.</h2><p class="muted">3 kW rooftop solar · Fictional project</p>${progressSteps(1)}${link('/customer/installation','View installation preview '+icon('arrow'),'btn primary')}</div></section><section class="panel next-step"><p class="eyebrow">YOUR NEXT STEP</p><h2>Clarity makes a<br>good decision easier.</h2><p class="muted">See what a side-by-side quotation comparison could look like.</p>${link('/customer/compare','Compare sample quotations '+icon('arrow'),'btn secondary')}</section></div>`; }
