function modulePage(path) { const [title,desc,headers,rows,action]=moduleData[path]; return `${heading('YOUR WORKSPACE',t(routes[path][1]),desc,`<button class="btn primary" disabled title="Available in a later phase">+ ${action} <span class="button-note">Later phase</span></button>`)}${demoNotice()}<section class="panel"><div class="panel-heading"><div><h2>${title}</h2><p class="muted">Clearly fictional records · Interface preview</p></div><label class="search-field">${icon('search')}<input id="record-search" type="search" placeholder="Search examples" aria-label="Search example records"></label></div><div class="table-scroll"><table><caption class="sr-only">${escapeHTML(routes[path][1])} fictional examples</caption><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody id="search-rows">${rows.map(row=>`<tr data-search="${escapeHTML(row.join(' ').toLowerCase())}">${row.map((cell,i)=>`<td>${i===0?`<strong>${cell}</strong>`:i===row.length-1?status(cell,'neutral'):cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div id="no-results" class="empty-inline" hidden>No examples match your search.</div><div class="table-foot">${rows.length} fictional examples <span>No live records are connected</span></div></section>${path==='/customer/quotations'?`<div class="center-cta">${link('/customer/compare','Compare fictional quotations '+icon('arrow'),'btn secondary')}</div>`:''}`; }
