function productDetail() { return `${heading('SOLAR SOLUTIONS','Rooftop solar, made for your space.','A product detail shell. Specifications and pricing are illustrative placeholders.') }<div class="detail-grid"><div class="product-art">${solarArtwork()}</div><section class="panel product-detail"><p class="eyebrow">CATEGORY PREVIEW · NO LIVE LISTING</p><h2>Your rooftop. New possibilities.</h2><p class="muted">A place to review system options, understand specifications and connect with a distributor.</p><dl><dt>System capacity</dt><dd>Determined after site assessment</dd><dt>Panel and inverter</dt><dd>Vendor specifications to follow</dd><dt>Warranty</dt><dd>To be provided by vendor</dd><dt>Price and availability</dt><dd>Not connected</dd></dl><button class="btn primary" disabled>Request quotation · Later phase</button>${link('/vendors','Explore distributor profile preview '+icon('arrow'),'text-link')}</section></div>`; }
